/* ENDURANCE interface. No account, telemetry, remote fonts, CDN, or API key required. */
(function(){'use strict';
const E=window.Endurance,D=E.D,app=document.getElementById('app'),modalRoot=document.getElementById('modal-root');
let state=null,view='garage',activeSlot=1,modal=null,tableTab='teams',timingTab='class',hireSlot=0,busy=false,storageOK=true,toastTimer=null;
const memory=new Map();const KEY=i=>'endurance-v1-slot-'+i;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(x,n=0)=>Number(x||0).toLocaleString('de-AT',{minimumFractionDigits:n,maximumFractionDigits:n});
const money=x=>num(x)+' €';const compact=x=>Math.abs(x)>=1000000?num(x/1000000,2)+' Mio. €':Math.abs(x)>=10000?num(x/1000,0)+' Tsd. €':money(x);
const duration=m=>m>=60?(m%60?Math.floor(m/60)+' h '+(m%60)+' min':m/60+' h'):m+' min';
const clock=m=>String(Math.floor(m/60)%24).padStart(2,'0')+':'+String(Math.floor(m%60)).padStart(2,'0');
const raceclock=r=>clock((r.event.startHour||14)*60+r.elapsed);
const initials=name=>String(name).split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const country=code=>/^[A-Z]{2}$/.test(code||'')?String.fromCodePoint(...[...code].map(x=>127397+x.charCodeAt(0))):'◈';
const categoryName=c=>({Bronze:'Bronze',Silver:'Silber',Gold:'Gold',Platinum:'Platin'}[c]||c);
const paths={home:'M3 10l9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z M9 21v-8h6v8',flag:'M5 21V3m0 1c5-4 9 4 14 0v10c-5 4-9-4-14 0',steering:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 10h18M9 10l3 5 3-5M12 15v6',team:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M17 4a4 4 0 0 1 0 7M22 21v-2a4 4 0 0 0-3-3.8',trophy:'M8 3h8v7a4 4 0 0 1-8 0zM8 5H4v2a4 4 0 0 0 4 4M16 5h4v2a4 4 0 0 1-4 4M12 14v6M8 21h8',calendar:'M8 2v4M16 2v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2M7 14h2M15 14h2M7 18h2',contract:'M14 2H5a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V9zM14 2v7h7M7 13h10M7 17h7',history:'M3 12a9 9 0 1 0 2.6-6.4L3 8M3 3v5h5M12 7v5l3 2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',arrow:'M5 12h14M13 6l6 6-6 6',chevron:'M9 5l7 7-7 7',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',upload:'M12 16V4M7 9l5-5 5 5M4 16v5h16v-5',close:'M6 6l12 12M6 18L18 6',check:'M4 12l5 5L20 6',moon:'M21 12.8A9 9 0 1 1 11.2 3 7 7 0 0 0 21 12.8',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1',rain:'M5 13a5 5 0 1 1 9-5 4 4 0 1 1 4 6H5M8 17l-1 3M13 17l-1 3M18 17l-1 3',wrench:'M15 3a6 6 0 0 0-7 8L2 17a3 3 0 0 0 4 4l6-6a6 6 0 0 0 9-7l-4 4-5-5z',bolt:'M13 2L4 14h7l-1 8 10-12h-7z',shield:'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6zM8 12l3 3 5-6',tyre:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0M6 6l3 3M15 15l3 3M6 18l3-3M15 9l3-3',chart:'M4 20h17M6 16v-4M12 16V8M18 16V3',help:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M9 8a3 3 0 0 1 6 1c0 2-3 2-3 4M12 17h.01',more:'M5 12h.01M12 12h.01M19 12h.01',save:'M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h12l4 4v12a2 2 0 0 1-2 2M7 3v6h9V3M7 21v-7h10v7',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',play:'M8 4l13 8-13 8z',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 11v6M12 7h.01'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.flag}"/></svg>`;
const brand=()=>`<div class="brand"><svg class="brand-mark" viewBox="0 0 34 38" aria-hidden="true"><path d="M10 2h24l-3 9H17l-2 5h15l-3 8H12l-2 5h17l-3 9H0z" fill="#71d6b3"/></svg><div class="brand-copy"><div class="brand-word">ENDURANCE</div><div class="brand-sub">GEMEINSAM BIS LE MANS</div></div></div>`;
let artId=0;
function carArt(){const id='paint'+artId++;return `<svg class="car-art" viewBox="0 0 720 345" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><defs><linearGradient id="${id}" x1="0" y1="0" x2="0.2" y2="1"><stop stop-color="#b7c7b5"/><stop offset=".48" stop-color="#6e8c78"/><stop offset="1" stop-color="#243b2b"/></linearGradient></defs><g transform="rotate(-9 350 180)"><ellipse cx="371" cy="269" rx="278" ry="29" fill="#07150d" opacity=".65"/><path d="M118 157l-13-37 73-3 9 44M118 134l-24 1-4-21 107-6 5 22-18 1" fill="#12271c" stroke="#5f7e66" stroke-width="2"/><path d="M125 185l27-44 99-15 54-41 122 3 80 51 99 16 54 47-3 42-26 14-490 2-37-20z" fill="url(#${id})" stroke="#9db5a0" stroke-width="1.7"/><path d="M281 132l40-35 97 2 59 39-108 5z" fill="#132b22" stroke="#657f70" stroke-width="2"/><path d="M336 100l13 41M419 101l28 38" stroke="#adc2aa" stroke-width="2"/><path d="M134 192l85-22 41-34 58 10-64 66-82 9zM510 148l43 41 108 19-43-42z" fill="#263f30" opacity=".8"/><path d="M143 237l451 5 45-16 24 9-29 32-481-2-41-24z" fill="#142c1d" stroke="#5f8064" stroke-width="2"/><path d="M258 161l47-6 60 67-53 14-37-33z" fill="#76d9b4"/><path d="M274 171l15-3 35 39-18 5z" fill="#d6e9dc"/><path d="M492 181l58 8 71 23-96 8-37-17z" fill="#476e51"/><path d="M562 184l53 16-3 10-57-13z" fill="#dcf4cf"/><path d="M571 187l38 11M568 191l38 11" stroke="#f8ffe8" stroke-width="2"/><path d="M146 196l25-4-7 13-22 3z" fill="#effbdc"/><path d="M366 151l95-6 47 53-137 26z" fill="#698871" stroke="#bdd2b8" stroke-width="1"/><text x="401" y="194" fill="#182d20" font-family="Arial,sans-serif" font-style="italic" font-size="43" font-weight="900">10</text><path d="M368 244l113 1M374 248l111 1" stroke="#71d6b3" stroke-width="2"/><path d="M190 258v-20a43 43 0 0 1 86 0v20M512 260v-24a43 43 0 0 1 86 0v24" fill="#0c1c12"/><g fill="#18231c" stroke="#51624e" stroke-width="3"><ellipse cx="233" cy="239" rx="31" ry="41"/><ellipse cx="555" cy="238" rx="31" ry="41"/></g><g fill="#324439" stroke="#6f866d" stroke-width="2"><ellipse cx="233" cy="239" rx="19" ry="28"/><ellipse cx="555" cy="238" rx="19" ry="28"/></g><g stroke="#859c78" stroke-width="3"><path d="M233 214v51M216 239h34M220 220l26 38M220 258l26-38M555 213v51M538 238h34M542 219l26 38M542 257l26-38"/></g><path d="M96 264h531" stroke="#78b784" stroke-width="1" opacity=".5"/></g></svg>`;}
const avatar=(d,large=false)=>`<div class="avatar ${d.id==='player'?'you':''} ${large?'large':''}" aria-hidden="true">${esc(initials(d.name))}</div>`;
const meter=(val,inverse=false)=>`<div class="meter ${inverse?val>60?'bad':val>25?'warn':'':val<20?'bad':val<40?'warn':''}"><span style="width:${E.clamp(val)}%"></span></div>`;
const metric=(title,value,sub)=>`<div class="panel metric"><span class="eyebrow">${title}</span><span class="value">${value}</span><small>${sub}</small></div>`;
const button=(label,action,style='primary',extra='')=>`<button class="btn ${style}" data-action="${action}" ${extra}>${label}</button>`;
const pageHead=(eyebrow,title,description,right='')=>`<header class="page-head"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${right}</header>`;
function readSlot(i){let raw,date='';try{raw=localStorage.getItem(KEY(i));date=localStorage.getItem(KEY(i)+'-date')||'';}catch{storageOK=false;raw=memory.get(i);}if(!raw)return null;try{return {state:E.parse(raw),date};}catch(err){return {error:err.message};}}
function save(){if(!state)return;const raw=E.serialise(state);memory.set(activeSlot,raw);try{localStorage.setItem(KEY(activeSlot),raw);localStorage.setItem(KEY(activeSlot)+'-date',new Date().toISOString());localStorage.setItem('endurance-last-slot',String(activeSlot));storageOK=true;}catch{storageOK=false;}}
function toast(message,error=false){const el=document.getElementById('toast');clearTimeout(toastTimer);el.textContent=message;el.className='show'+(error?' error':'');toastTimer=setTimeout(()=>el.className='',error?6500:3400);}
function mutate(fn,message){const before=state?JSON.stringify(state):null;try{fn();save();render();if(message)toast(message);}catch(err){if(before)state=E.parse(before);toast(err.message||'Die Aktion konnte nicht abgeschlossen werden.',true);render();}}
function navigate(next){view=next;if(view==='race'&&!state?.race)view=state?.phase==='offseason'?'market':'garage';modal=null;render();window.scrollTo({top:0});}
function openSlot(i){const saved=readSlot(i);if(!saved||saved.error){toast(saved?.error||'Dieser Speicherplatz ist leer.',true);return;}activeSlot=i;state=saved.state;view=state.race?'race':state.phase==='offseason'?'market':'garage';modal=null;render();window.scrollTo(0,0);}
function savedCards(settings=false){return `<div class="grid3">${[1,2,3].map(i=>{const saved=readSlot(i),s=saved?.state;return `<div class="save-card"><div class="row between"><span class="eyebrow" style="margin:0">SPEICHERPLATZ 0${i}</span>${state&&i===activeSlot?'<span class="badge">AKTIV</span>':''}</div><h3>${s?esc(s.player.name):saved?.error?'Nicht lesbarer Spielstand':'Ein neues Kapitel'}</h3><p>${s?`${s.role==='driver'?'Fahrer':'Manager'} · ${esc(s.classId)} · Saison ${s.season}<br>${esc(s.team.name)}`:saved?.error?'Die Daten werden nicht automatisch überschrieben.':'Hier ist Platz für eine weitere Karriere.'}</p><div class="row wrap gap8">${s?`<button class="btn ${settings?'ghost':'primary'} small-btn" data-load="${i}">${settings?'Laden':'Weiterspielen'}</button>`:''}${settings&&state?`<button class="btn ghost small-btn" data-copy="${i}">Hier sichern</button>`:''}${settings&&saved?`<button class="icon-btn" data-delete="${i}" aria-label="Speicherplatz ${i} löschen">${icon('trash')}</button>`:''}</div></div>`;}).join('')}</div>`;}
function renderHome(){return `<div class="landing"><header class="landing-header">${brand()}${button(icon('help')+' Spielhilfe','help','ghost')}</header><main id="main" style="padding:0"><section class="landing-hero"><div class="hero-number">24</div><div class="hero-copy"><span class="eyebrow">DEINE KARRIERE. EUER GEMEINSAMES RENNEN.</span><h1 class="hero-title">Ein Auto.<br>Drei Fahrer.<br><span>Dein Weg.</span></h1><p>Von der ersten GT4-Saison bis zur Zielflagge in Le Mans. Entscheide im Cockpit. Denke an dein Team. Bestehe die Nacht.</p><div class="hero-small"><span>Fahrer & Manager</span><span>5 Fahrzeugklassen</span><span>Offline spielbar</span></div></div><div class="hero-art">${carArt()}</div></section><section class="home-options"><article class="mode-card"><span class="mode-icon">${icon('steering')}</span><span class="eyebrow">01 / IM COCKPIT</span><h2>Deine Fahrerkarriere.</h2><p>Starte in GT4. Entwickle deine Stärken, finde dein Team und übergib mehr als nur das Lenkrad.</p>${button('Fahrerkarriere starten '+icon('arrow'),'new-driver','primary')}</article><article class="mode-card"><span class="mode-icon">${icon('team')}</span><span class="eyebrow">02 / AN DER BOXENMAUER</span><h2>Dein Team. Dein Plan.</h2><p>Übernimm ein Team in deiner Wunschklasse. Verpflichte Fahrer und manage jeden Stint bis ins Ziel.</p>${button('Managerkarriere starten '+icon('arrow'),'new-manager','light')}</article></section><section class="challenge"><div><span class="eyebrow amber" style="margin-bottom:6px">DIREKT INS GROSSE RENNEN</span><h3>24h-Challenge: Le Mans</h3><p>Ein eigener Spielstand im Hypercar – zum sofortigen Ausprobieren der Langstrecke.</p></div>${button('Die Nacht beginnt '+icon('moon'),'challenge','ghost')}</section>${[1,2,3].some(i=>readSlot(i))?`<div class="section-title"><h2>Deine Spielstände</h2><span class="pill">Lokal auf diesem Gerät</span></div>${savedCards()}`:''}<div class="home-foot"><span>ENDURANCE 1.0 · EIN EIGENSTÄNDIGES ENTSCHEIDUNGSSPIEL</span><span>Keine Anmeldung. Keine In-App-Käufe. Fiktive Teams & Spielkalender.</span><button class="link-btn" data-action="import">Spielstand importieren</button></div></main></div>`;}
const navs=[['garage','home','Übersicht'],['race','flag','Rennzentrale'],['team','team','Team & Garage'],['standings','trophy','Meisterschaft'],['calendar','calendar','Rennkalender'],['market','contract','Karriere & Verträge'],['history','history','Deine Chronik'],['settings','settings','Speichern & Hilfe']];
function shell(content){const title=navs.find(x=>x[0]===view)?.[2]||'Übersicht';const s=state;return `<aside class="sidebar">${brand()}<span class="nav-label">DEIN PADDOCK</span><nav class="nav-list" aria-label="Hauptnavigation">${navs.map(([id,ico,label])=>`<button class="nav-item ${view===id?'active':''}" data-nav="${id}" title="${label}">${icon(ico)}<span class="nav-text">${label}</span>${id==='race'&&s.race&&!s.race.finished?'<i class="nav-dot"></i>':''}</button>`).join('')}</nav><div class="sidebar-spacer"></div><button class="nav-item" data-action="home" title="Zum Hauptmenü">${icon('chevron')}<span class="nav-text">Hauptmenü</span></button><div class="sidebar-profile"><div class="row">${avatar(s.player)}<div class="profile-copy"><b>${esc(s.player.name)}</b><small>${s.role==='driver'?'Fahrerkarriere':'Teammanager'} · ${s.classId}</small></div></div></div></aside><div class="shell"><header class="topbar"><div class="breadcrumb">PADDOCK <span style="padding:0 12px;color:#4d6655">/</span> <b>${title}</b></div><div class="mobile-brand">${brand()}</div><div class="topbar-actions"><span class="mode">${s.mode==='quick'?'SCHNELLMODUS':'STANDARDMODUS'}</span><span class="row save-text small"><i class="save-dot" style="${storageOK?'':'background:var(--amber)'}"></i>${storageOK?'Lokal gespeichert':'Bitte exportieren'}</span><button class="btn ghost small-btn" data-nav="standings">${icon('trophy')} Tabelle</button><button class="icon-btn" data-action="export" aria-label="Spielstand exportieren" title="Spielstand exportieren">${icon('download')}</button></div></header><main id="main">${content}<footer class="footer-note">ENDURANCE · Ein Auto. Ein Team. Ein gemeinsames Ergebnis. · Saison ${s.year} ist eine Spielwelt.</footer></main><nav class="bottom-nav" aria-label="Mobile Navigation">${[['garage','home','Übersicht'],['race','flag','Rennen'],['team','team','Team'],['standings','trophy','Tabelle']].map(([id,ico,label])=>`<button data-nav="${id}" class="${view===id?'active':''}">${icon(ico)}<span>${label}</span></button>`).join('')}<button data-action="more" class="${['calendar','market','history','settings'].includes(view)?'active':''}">${icon('more')}<span>Mehr</span></button></nav></div>${storageOK?'':`<div class="storage-banner">Automatisches Speichern ist in diesem Browser nicht verfügbar. Bitte nutze „Spielstand exportieren“, bevor du die Seite schließt.</div>`}`;}
function renderGarage(){const s=state;if(s.race)return `${pageHead('DEIN RENNWOCHENENDE','Ein Rennen wartet auf dich.','Dein Spielstand bleibt genau an der aktuellen Entscheidung stehen.')}<div class="event-hero"><div class="event-copy"><span class="badge">${s.race.finished?'ERGEBNIS BEREIT':'RENNEN PAUSIERT'}</span><h2>${esc(s.race.event.name)}</h2><p>${duration(s.race.elapsed)} von ${duration(s.race.event.minutes)} · ${s.classId}</p><button class="btn primary" data-nav="race">${s.race.finished?'Zum Rennergebnis':'Ins Rennen zurück'} ${icon('arrow')}</button></div>${carArt()}</div>`;
 if(s.phase==='offseason')return renderMarket();const ev=E.event(s),st=E.standings(s),teamrow=st.teams.find(t=>t.id==='own');const rank=s.history.some(h=>h.season===s.season)?'P'+(st.teams.indexOf(teamrow)+1):'–';const training=s.role==='driver'?[['pace','bolt','Tempo trainieren','Dein Tempo +1,7'],['wet','rain','Regen trainieren','Deine Regenstärke +1,7'],['night','moon','Nacht trainieren','Deine Nachtstärke +1,7'],['tyre','tyre','Reifen verstehen','Dein Reifenwert +1,7'],['teamwork','team','Teamwork stärken','Teamwork +2,2 · Moral +5'],['rest','shield','Kräfte sammeln','Mehr Wochenend-Bonus']]:[['setup','wrench','Abstimmung testen','Mehr Pace an diesem Wochenende'],['pitdrill','bolt','Boxenstopps üben','Kürzere Stopps an diesem Wochenende'],['reliability','shield','Haltbarkeit prüfen','Weniger technische Risiken'],['teamwork','team','Teambriefing','Teammoral +6']];
 return `${pageHead(`SAISON ${String(s.season).padStart(2,'0')} / ${s.role==='driver'?'FAHRERKARRIERE':'MANAGERKARRIERE'}`,'Bereit für das nächste Kapitel?','Runde '+(s.round+1)+' von '+s.calendar.length+' · '+esc(D.CLASSES[s.classId].series),`<span class="badge">${esc(s.classId)}</span>`)}<section class="event-hero"><div class="event-number">${ev.special?'24':'10'}</div><div class="event-copy"><span class="eyebrow">NÄCHSTES RENNEN · ${country(ev.country)} ${esc(ev.label.toUpperCase())}</span><h2>${esc(ev.name)}</h2><p>${duration(ev.minutes)} · ${esc(ev.character)}${ev.lmgt3?' · LMGT3-Einladung':''}</p>${button('Qualifying & Rennen starten '+icon('arrow'),'start-race','primary')}</div>${carArt()}<span class="track-tag">${ev.special?'DURCH DIE NACHT. ZUSAMMEN.':esc(E.carLabel(s))}</span></section><div class="grid4 space-bottom">${metric('TEAMWERTUNG',rank,num(teamrow.points)+' Meisterschaftspunkte')}${metric('DEIN RUF',num(s.reputation)+'/100','Öffnet Türen im Fahrerlager')}${metric(s.role==='manager'?'TEAM-BUDGET':'DEINE VERDIENSTE',compact(s.role==='manager'?s.team.budget:s.money),s.role==='manager'?'Für Fahrer & Entwicklung':'Fiktive Spielbeträge')}${metric('ZUSAMMENHALT',num(s.team.morale)+'%','Ein Ergebnis, drei Persönlichkeiten')}</div><div class="garage-split"><div class="stack"><section class="panel"><div class="panel-head"><div><h2>Vor dem Start</h2><p>Eine Vorbereitung pro Rennwochenende. Ohne Zusatzkosten.</p></div><span class="badge ${s.prep.used?'':'grey'}">${s.prep.used?'ERLEDIGT':'1 ENTSCHEIDUNG'}</span></div><div class="training-grid">${training.map(([id,ico,name,desc])=>`<button class="training ${s.prep.action===id?'selected':''}" data-prepare="${id}" ${s.prep.used?'disabled':''} aria-label="${name}">${icon(s.prep.action===id?'check':ico)}<b>${name}</b><span>${desc}</span></button>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h2>Euer Stintplan</h2><p>Die Box führt Tankstopps und geplante Wechsel automatisch aus.</p></div>${icon('contract')}</div><div class="form-grid"><label class="field">Wer startet?<select data-plan="start">${driverOptions(s.prep.start)}</select></label><label class="field">Fahrerwechsel<select data-plan="plan"><option value="rotation" ${s.prep.plan==='rotation'?'selected':''}>Feste Rotation</option><option value="conditions" ${s.prep.plan==='conditions'?'selected':''}>Nach Bedingungen</option></select></label><label class="field">Bevorzugt in der Nacht<select data-plan="night" ${s.prep.plan==='rotation'?'disabled':''}>${driverOptions(s.prep.night)}</select></label><label class="field">Bevorzugt im Schlussstint<select data-plan="finish" ${s.prep.plan==='rotation'?'disabled':''}>${driverOptions(s.prep.finish)}</select></label><label class="field">Reifenstrategie<select data-plan="tyres"><option value="double" ${s.prep.tyres==='double'?'selected':''}>Mehrere Stints pro Reifensatz</option><option value="fresh" ${s.prep.tyres==='fresh'?'selected':''}>Frische Reifen bei jedem Stopp</option></select></label><label class="field">Qualifying-Risiko<select data-plan="qualifying"><option value="safe" ${s.prep.qualifying==='safe'?'selected':''}>Sichere Runde</option><option value="balanced" ${s.prep.qualifying==='balanced'?'selected':''}>Ausgewogen</option><option value="attack" ${s.prep.qualifying==='attack'?'selected':''}>Alles auf eine Runde</option></select></label></div><p class="small muted" style="margin-top:14px">${ev.minutes<=180?'Bei diesem kurzen Rennen sind zwei Fahrer aktiv; der dritte ist Reserve. Du wirst in der Fahrerkarriere immer berücksichtigt.':'Alle drei Fahrer teilen sich das Auto. Müdigkeit und nötige Ruhezeiten können einen Wunschstint verhindern.'} Nacht- und Schlusspräferenzen gelten im Plan „Nach Bedingungen“.</p></section></div><div class="stack"><section class="panel"><div class="panel-head"><div><h2>${esc(s.team.name)}</h2><p>${esc(E.carLabel(s))} · ${s.role==='driver'?'Deine Mannschaft':'Dein Programm'}</p></div><button class="link-btn" data-nav="team">Team ansehen →</button></div>${s.team.drivers.map(d=>`<div class="driver-mini">${avatar(d)}<div><div class="name">${esc(d.name)} ${d.id==='player'?'<span class="tiny green">DU</span>':''}</div><small>${categoryName(d.category)} · ${esc(d.specialty)}</small></div><span class="score">${num(E.average(d))}</span></div>`).join('')}<div class="divider"></div><div class="stat-line"><span>Fahrzeugabstimmung</span><b>${num(s.team.quality)}/100</b></div>${meter(s.team.quality)}<div class="stat-line" style="margin-top:13px"><span>Boxencrew</span><b>${num(s.team.pitCrew)}/100</b></div>${meter(s.team.pitCrew)}</section><section class="panel"><div class="panel-head"><h2>Aus dem Fahrerlager</h2>${icon('flag')}</div>${s.news.slice(0,3).map(n=>`<div class="news-item"><i class="news-dot"></i><div><b>${esc(n.title)}</b><p>${esc(n.text)}</p></div></div>`).join('')}</section></div></div>`;
}
function driverOptions(selected,drivers=state.team.drivers,active=null){return drivers.map((d,i)=>`<option value="${i}" ${Number(selected)===i?'selected':''} ${active&&!active.includes(i)?'disabled':''}>${esc(d.name)}${d.id==='player'?' (du)':''}${active&&!active.includes(i)?' · Reserve':''}</option>`).join('');}
function gap(r,c,leader){if(c.status==='dnf')return 'DNF';if(c===leader)return 'FÜHREND';const laps=leader.progress-c.progress;if(laps>=1)return '+'+Math.floor(laps)+' R';return '+'+num(laps*(leader.lastLap||90),1)+' s';}
function timingTable(s){const r=s.race,rows=E.ranked(r,timingTab==='class'?s.classId:null),leader=rows.find(c=>c.status!=='dnf')||rows[0];return `<section class="panel timing-panel"><div class="panel-head"><h3>Live-Klassement</h3><span class="badge live">${s.race.finished?'FINAL':'LIVE'}</span></div><div class="switch-group" style="margin-bottom:15px"><button data-timing="class" class="${timingTab==='class'?'active':''}">Deine Klasse</button><button data-timing="all" class="${timingTab==='all'?'active':''}">Gesamt</button></div><div class="timing-scroll"><table class="timing"><thead><tr><th>P</th><th>Team</th><th>Abstand</th></tr></thead><tbody>${rows.map((c,i)=>`<tr class="${c.own?'own':''}"><td class="num">${i+1}</td><td><div class="team-name">${esc(c.name)}</div><div class="class-label"><span class="car-number">#${c.number}</span> · ${c.classId==='GT3'&&r.event.id==='lemans'?'LMGT3':c.classId}</div></td><td>${gap(r,c,leader)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function renderRace(){const s=state;if(!s.race)return renderGarage();if(s.race.finished)return renderResult();const r=s.race,c=E.ownCar(s),current=c.drivers[c.driver],wet=E.getWeather(r),forecast=E.forecast(s),day=E.timeOfDay(r),remaining=r.event.minutes-r.elapsed;
 const meterCard=(title,val,inverse=false)=>`<div class="race-meter"><span class="eyebrow">${title}</span><span class="value">${num(val)}<span class="tiny muted"> %</span></span>${meter(val,inverse)}</div>`;
 return `<header class="race-head"><div><span class="eyebrow">${esc(s.classId)} / ${r.event.special?'DAS GROSSE LANGSTRECKENRENNEN':'RENNZENTRALE'}</span><h1>${duration(r.event.minutes)} ${esc(r.event.name)}</h1></div><div class="clock-card"><div><small>ORTSZEIT IM SPIEL</small><strong>${raceclock(r)}</strong><small>${day} · Noch ${duration(remaining)}</small></div></div></header><div class="race-grid"><div><section class="race-visual ${E.isNight(r)?'night':day==='Abend'?'evening':''}"><div class="race-visual-content"><span class="badge ${r.flag==='green'?'live':'amber'}">${r.flag==='green'?'RENNEN AKTIV':r.flag==='sc'?'SAFETY CAR':'FULL COURSE YELLOW'}</span><h2>${c.status==='dnf'?'DNF':'P'+E.racePosition(s)} <span style="font-size:13px;letter-spacing:0;color:#b5cab8">IN DEINER KLASSE</span></h2><p>${esc(current.name)} · ${s.role==='manager'?'DU MANAGST DEN STINT':current.id==='player'?'DU SITZT AM STEUER':'DEIN TEAMKOLLEGE FÄHRT'}</p><div class="row" style="margin-top:13px"><span class="pill">${c.compound==='wet'?'Regenreifen':'Slicks'}</span><span class="pill">${c.stops} Stopps</span><span class="pill">${wet>=60?'Regen':wet>0?'Feucht':'Trocken'}</span></div></div>${carArt()}</section><div class="race-progress">${meter(r.elapsed/r.event.minutes*100)}<div class="race-phase"><span>Start</span><span>${duration(r.elapsed)} gefahren</span><span>${duration(r.event.minutes)} · Ziel</span></div></div><div class="race-meters">${meterCard('TANK',c.fuel)}${meterCard('REIFEN',c.tyres)}${meterCard('SCHADEN',c.damage,true)}${meterCard('ERMÜDUNG',c.fatigue[c.driver],true)}</div>${r.lastSummary?`<div class="last-action"><div class="row between"><b>${esc(r.lastSummary.title)}</b><span class="position-shift">P${r.lastSummary.fromPosition} → P${r.lastSummary.position}</span></div><p>${clock(r.lastSummary.from)}–${clock(r.lastSummary.to)} Rennzeit · ${esc(r.lastSummary.driver)} zu Beginn des Kapitels${r.lastSummary.damageChange>1?' · Neuer Schaden: +'+num(r.lastSummary.damageChange)+' %':''}. Geplante Stopps und Wechsel wurden mitsimuliert.</p></div>`:''}<section class="decision" id="decision"><span class="decision-index">${String(r.decisions+1).padStart(2,'0')}</span><span class="eyebrow green">${r.prompt.kind==='rest'?'ZWISCHEN DEINEN STINTS':'DEINE NÄCHSTE ENTSCHEIDUNG'}</span><h2>${esc(r.prompt.title)}</h2><p>${esc(r.prompt.text)}</p><div class="choices">${E.choices(s).map((ch,i)=>`<button class="choice" data-choice="${ch.id}"><span class="key">${i+1}</span><span><b>${esc(ch.title)}</b><small>${esc(ch.desc)}</small><span class="choice-tag">${esc(ch.tag)}</span></span><span class="choice-arrow">→</span></button>`).join('')}</div></section><div class="race-actions">${button(icon('wrench')+' Boxenauftrag','pit','ghost',c.lastManual===r.decisions||c.status==='dnf'?'disabled':'')}<small>Ein Klick simuliert bis zu ${duration(r.decisionMinutes)}. Ohne Entscheidung bleibt die Zeit stehen.</small></div><section class="panel radio"><div class="panel-head"><h3>Teamfunk & Rennverlauf</h3><span class="pill">${r.log.length} Meldungen</span></div>${r.log.slice(-6).reverse().map(n=>`<div class="radio-entry ${n.kind}"><span class="radio-time">${clock(n.at)}</span><div><b>${esc(n.title)}</b><p>${esc(n.text)}</p></div></div>`).join('')}</section></div><aside class="race-aside">${timingTable(s)}<section class="panel crew-panel" style="margin-top:16px"><div class="panel-head"><h3>Ein Auto. Eure Stints.</h3>${icon('team')}</div>${c.drivers.map((d,i)=>`<div class="crew-live ${c.driver===i?'active':''}"><div class="row between"><div class="row">${avatar(d)}<div><div class="name">${esc(d.name)}</div><small>${c.driver===i?'IM COCKPIT':c.active.includes(i)?'IN DER BOX':'RESERVE'} · ${duration(Math.round(c.driveMinutes[i]))} gefahren</small></div></div><span class="num small">${num(c.fatigue[i])}%</span></div>${meter(c.fatigue[i],true)}</div>`).join('')}<p class="tiny muted" style="margin-top:13px">Die Balken zeigen Ermüdung. Pause senkt sie. Reifen und Schaden gehören dem Auto, nicht dem Fahrer.</p></section><section class="panel weather-panel" style="margin-top:16px"><div class="panel-head"><h3>Wetterradar</h3>${icon(wet>0?'rain':E.isNight(r)?'moon':'sun')}</div><p class="small">${forecast.text}</p><div class="row between" style="margin-top:13px"><span class="tiny muted">Vorschau bis ${duration(forecast.minutes)}</span><span class="badge grey">${forecast.wet>=60?'NASS':forecast.wet>0?'FEUCHT':'TROCKEN'}</span></div><div class="divider"></div><button class="link-btn" data-nav="standings">Meisterschaft ansehen – Zeit bleibt stehen →</button><button class="link-btn" data-action="qualifying" style="margin-top:10px">Qualifying-Ergebnis ansehen →</button></section></aside></div>`;
}
function renderResult(){const s=state,r=s.race,res=r.result,c=E.ownCar(s),order=E.ranked(r,s.classId),title=res.dnf?'Nicht das Ende eurer Geschichte.':res.position===1?'Ihr habt es gemeinsam geschafft.':res.position<=3?'Dieses Podium gehört euch allen.':res.position<res.expected?'Mehr herausgeholt als erwartet.':'Eine Zielflagge. Viele Entscheidungen.';
 const last=s.round===s.calendar.length-1;return `${pageHead('ZIelflagge / '+esc(s.classId),esc(res.eventName),'Saison '+s.season+' · Runde '+(s.round+1))}<section class="result-hero ${res.dnf?'bad':''}"><div class="result-position">${res.dnf?'DNF':'P'+res.position}</div><div class="result-copy"><span class="eyebrow green">${res.dnf?'RÜCKSCHLAG, KEIN KARRIEREENDE':s.classId==='Hypercar'&&r.event.id==='lemans'&&res.position===1?'GESAMTSIEG IN LE MANS':r.event.id==='lemans'?'KLASSENERGEBNIS IN LE MANS':'GEMEINSAMES TEAMERGEBNIS'}</span><h1>${title}</h1><p>${res.dnf?'Die Schäden haben euren Einsatz beendet. Erfahrung, Chronik und dein nächster Vertrag bleiben erreichbar.':`Mit diesem Auto lag die vereinfachte Erwartung bei P${res.expected}. Ihr erreicht P${res.position} in der Klasse${r.event.multiclass?' und P'+res.overall+' gesamt':''}. Alle tatsächlich eingesetzten Fahrer erhalten dieselben Klassenpunkte.`}</p>${button((last?'Zur Saisonbilanz':'Zum nächsten Rennwochenende')+' '+icon('arrow'),'next-round','primary')}</div></section><div class="grid4">${metric('MEISTERSCHAFT','+'+res.points,'Punkte für eingesetzte Fahrer & Team')}${metric('DEIN RUF','+'+num(res.repGain,1),'Leistung relativ zur Auto-Erwartung')}${metric('TEAM-ERGEBNIS',compact(res.net),'Einnahmen minus laufende Kosten')}${metric('BOXENSTOPPS',res.stops,`${res.errors} Fehler · ${num(res.damage)} % Restschaden`)}</div><div class="grid2 space-top"><section class="panel"><div class="panel-head"><h2>Drei Fahrer. Ein Ergebnis.</h2>${icon('team')}</div><div class="stint-share">${res.drivers.map(d=>`<span style="width:${d.minutes/r.event.minutes*100}%" title="${esc(d.name)}: ${duration(d.minutes)}"></span>`).join('')}</div>${res.drivers.map(d=>`<div class="driver-mini"><div class="avatar ${d.id==='player'?'you':''}">${esc(initials(d.name))}</div><div><div class="name">${esc(d.name)}</div><small>${d.minutes>0?duration(Math.round(d.minutes))+' im Auto':'Reserve – nicht eingesetzt'}</small></div><span class="score" style="font-size:16px">${d.minutes>0?'+'+res.points:'–'}</span></div>`).join('')}<div class="note space-top">${res.errors===0?'Ohne Fahrfehler durchgekommen.':'Ein Fehler betraf das gemeinsame Auto – auch die späteren Stints.'} ${r.event.minutes>=1440?'Alle Nacht-, Wetter- und Fahrerwechsel wurden bis zur Zielflagge simuliert.':''}</div></section><section class="panel"><div class="panel-head"><h2>Nach dem Rennen</h2><span class="badge ${s.prep.interviewed?'':'grey'}">${s.prep.interviewed?'BEANTWORTET':'INTERVIEW'}</span></div><p class="small">„Was nimmst du aus diesem Rennen mit?“</p><div class="choices">${[['team','„Dieses Ergebnis gehört der ganzen Mannschaft.“','Teammoral +4'],['ambition','„Wir haben noch größere Ziele.“','Dein Ruf +1'],['honest','„Wir schauen uns unsere Fehler genau an.“','Deine Konstanz +0,6']].map(([id,txt,sub])=>`<button class="choice" data-interview="${id}" ${s.prep.interviewed?'disabled':''}><span><b>${txt}</b><small>${sub}</small></span><span class="choice-arrow">→</span></button>`).join('')}</div></section></div><div class="grid2 space-top"><section class="panel"><h2>Das Klassenpodium</h2><div class="podium">${[1,0,2].map(i=>{const car=order[i];return `<div class="podium-block ${i===0?'first':''}"><strong>${i+1}</strong><p>${esc(car?.name||'–')}</p></div>`;}).join('')}<span class="hidden"></span></div><div class="divider"></div><div class="stat-line"><span>Einnahmen inkl. Sponsor</span><b>${money(res.income)}</b></div><div class="stat-line"><span>Betrieb & Reparaturen</span><b>−${money(res.expenses)}</b></div><div class="stat-line"><span>Sponsor-Erfolgsbonus enthalten</span><b>${money(res.sponsorBonus*D.CLASSES[s.classId].scale)}</b></div></section>${timingTable(s)}</div>`;
}
function renderStandings(){const s=state,rows=E.standings(s)[tableTab];return `${pageHead('SAISON '+s.season+' / '+esc(D.CLASSES[s.classId].series),'Jeder Punkt gehört zum Weg.','Offizielle Spielwertung aus abgeschlossenen Rennen. Ein laufendes Rennen ist noch nicht eingerechnet.',s.race?`<button class="btn primary small-btn" data-nav="race">Zurück zum Rennen ${icon('arrow')}</button>`:'')}<div class="row between wrap space-bottom"><div class="switch-group"><button data-table="teams" class="${tableTab==='teams'?'active':''}">Teamwertung</button><button data-table="drivers" class="${tableTab==='drivers'?'active':''}">Fahrerwertung</button></div><span class="badge grey">${s.history.filter(h=>h.season===s.season).length}/${s.calendar.length} RENNEN GEWERTET</span></div><section class="panel"><div class="big-table-wrap"><table class="big-table"><thead><tr><th>Pos.</th><th>${tableTab==='teams'?'Team':'Fahrer / Team'}</th>${tableTab==='drivers'?'<th class="optional-col">Einstufung</th>':''}<th class="optional-col">Siege</th><th class="optional-col">Podien</th><th>Punkte</th></tr></thead><tbody>${rows.map((x,i)=>`<tr class="${x.own?'own':''}"><td>${i+1}</td><td>${tableTab==='drivers'?country(x.country)+' ':''}${esc(x.name)} ${x.player?'<span class="badge">DU</span>':''}${tableTab==='drivers'?`<span class="team-sub">${esc(x.team)}</span>`:x.own?'<span class="team-sub">Deine Mannschaft</span>':''}</td>${tableTab==='drivers'?`<td class="optional-col">${categoryName(x.category)}</td>`:''}<td class="optional-col">${x.wins}</td><td class="optional-col">${x.podiums}</td><td>${x.points}</td></tr>`).join('')}</tbody></table></div><p class="table-note">Spielwertung: 25–18–15–12–10–8–6–4–2–1. 24h-Rennen geben doppelte Punkte. Ausfälle geben keine Punkte. Bei Gleichstand zählen Siege, Podien und bestes Ergebnis; danach alphabetische Anzeige. Ein Auto pro Team in dieser Version.</p></section>${s.race&&!s.race.finished?'<div class="note space-top">Das Rennen ist pausiert. Tabellen, Teamseiten und Kalender zu öffnen verändert die Simulation nicht.</div>':''}`;}
function driverCard(d,i){return `<article class="panel driver-card"><span class="card-number">0${i+1}</span><div class="row between">${avatar(d,true)}<div class="center"><span class="driver-score">${num(E.average(d))}</span><div class="eyebrow" style="font-size:7px;margin:0">GESAMTWERT</div></div></div><h3>${country(d.country)} ${esc(d.name)}</h3><div class="row wrap"><span class="category green">${categoryName(d.category)}</span><span class="pill">${d.id==='player'?'DU':esc(d.specialty)}</span></div><div class="stats-grid">${Object.entries(D.STAT_LABELS).map(([key,name])=>`<div><div class="stat-line"><span>${name}</span><b>${num(d[key])}</b></div>${meter(d[key])}</div>`).join('')}</div></article>`;}
function renderTeam(){const s=state,manage=s.role==='manager',locked=s.phase!=='preparation'||!!s.race;return `${pageHead(esc(s.team.brand.toUpperCase())+' / '+esc(s.classId),esc(s.team.name),'Fahrer mit eigenen Stärken. Ein Auto, das ihr gemeinsam ins Ziel bringt.',`<span class="badge">${manage?'TEAMMANAGEMENT':'DEINE CREW'}</span>`)}<div class="grid3">${s.team.drivers.map(driverCard).join('')}</div><div class="section-title"><h2>Auto & Mannschaft</h2><span class="pill">${esc(E.carLabel(s))}</span></div><div class="grid3">${[['quality','Abstimmung','Setuparbeit und Streckenabstimmung. Keine frei erfundene Motorfreigabe.'],['pitCrew','Boxencrew','Bessere Abläufe verkürzen die Standzeit bei allen Fahrern.'],['reliability','Zuverlässigkeit','Vorbereitung und Wartung verringern das Risiko technischer Probleme.']].map(([key,name,desc])=>`<section class="upgrade-card"><div class="row between"><h3>${name}</h3>${icon(key==='quality'?'wrench':key==='pitCrew'?'bolt':'shield')}</div><div class="value">${num(s.team[key])}<span class="small muted"> / 100</span></div>${meter(s.team[key])}<p style="margin-top:15px">${desc}</p>${manage?`<button class="btn ghost full" data-upgrade="${key}" ${locked||s.team.budget<E.upgradeCost(s,key)||s.team[key]>=96?'disabled':''}>+3 verbessern · ${compact(E.upgradeCost(s,key))}</button>`:''}</section>`).join('')}</div><div class="note space-top">${manage?'Team-Budget: '+money(s.team.budget)+'. Verbesserungen und Fahrerwechsel sind nur vor dem Rennen möglich.':'Als Fahrer entscheidet deine Teamleitung über Personal und Technik. Du entwickelst deine Fähigkeiten in der Wochenend-Vorbereitung.'} Alle Leistungswerte und Geldbeträge sind Spielwerte.</div>${manage?`<div class="section-title"><h2>Fahrermarkt</h2><span class="badge grey">ANGEBOTE FÜR DIESE RUNDE</span></div><div class="row wrap space-bottom"><label class="field" style="min-width:240px;max-width:100%">Welchen Platz möchtest du neu besetzen?<select id="hire-slot">${driverOptions(hireSlot)}</select></label><p class="tiny" style="max-width:380px">Neue Fahrer übernehmen den gewählten Platz. Bereits erzielte persönliche Punkte bleiben beim bisherigen Fahrer.</p></div><div class="grid3">${E.candidates(s).map(d=>`<article class="market-candidate"><div class="row between">${avatar(d)}<span class="badge grey">${categoryName(d.category)}</span></div><h3>${country(d.country)} ${esc(d.name)}</h3><p>${esc(d.specialty)} · Gesamt ${num(E.average(d))}</p><div class="stat-line"><span>Nacht / Regen / Konstanz</span><b>${num(d.night)} / ${num(d.wet)} / ${num(d.consistency)}</b></div><div class="price">${money(d.price)} <span class="tiny muted">einmalig</span></div><button class="btn ghost full small-btn" data-hire="${d.id}" ${locked||s.team.budget<d.price||s.team.drivers.some(x=>x.id===d.id)?'disabled':''}>${s.team.drivers.some(x=>x.id===d.id)?'Bereits im Team':'Verpflichten'}</button></article>`).join('')}</div><p class="small muted space-top">Vereinfachte Besetzungsprüfung: Für LMGT3 ein Bronze-Fahrer und höchstens ein Gold/Platin-Fahrer. Für LMP2/LMP3 mindestens ein Bronze/Silber-Fahrer. Die übrigen Detailregeln realer Serien sind nicht vollständig abgebildet.</p>`:''}<div class="section-title"><h2>Euer Saisonpartner</h2><span class="pill">${s.sponsorPicked?'Vertrag unterschrieben':'Einmal pro Saison wählbar'}</span></div><div class="grid3">${D.SPONSORS.map(sp=>`<article class="sponsor-card ${s.team.sponsor===sp.id?'selected':''}"><span class="eyebrow">${sp.tag}</span><h3>${sp.name}</h3><p>${sp.text}</p><div class="stat-line"><span>Pro Rennen</span><b>${compact(sp.base*D.CLASSES[s.classId].scale)}</b></div><div class="stat-line"><span>Erfolgsbonus</span><b>${compact(sp.bonus*D.CLASSES[s.classId].scale)}</b></div><button class="btn ${s.team.sponsor===sp.id?'primary':'ghost'} full small-btn" data-sponsor="${sp.id}" ${locked||s.sponsorPicked?'disabled':''}>${s.team.sponsor===sp.id?(s.sponsorPicked?'Aktiver Partner':'Diesen Partner bestätigen'):'Partner wählen'}</button></article>`).join('')}</div>`;}
function renderCalendar(){const s=state;return `${pageHead('DEINE SAISON '+s.year,'Eine Saison. Viele Arten zu bestehen.','Ein bewusst kompakter Spielkalender – keine Wiedergabe des offiziellen Rennkalenders.')}<div class="note space-bottom">${s.classId==='GT4'?'Dein Einstieg verbindet kurze Rennen mit ersten längeren Einsätzen.':s.classId==='GT3'?'GT3 bleibt ein eigener Karriereweg. In Le Mans startet dein Team in LMGT3 auf Einladung der Spielwelt.':s.classId==='LMP3'?'LMP3 führt dich an den Prototypen-Sport heran. Le Mans erreichst du hier über einen späteren Wechsel in LMP2.':'Le Mans ist ein Saisonhöhepunkt, keine eigene Fahrzeugklasse.'} ${s.mode==='quick'?'Schnellmodus: größere Zeitsprünge.':'Standardmodus: mehr Rennentscheidungen.'}</div>${s.calendar.map((ev,i)=>{const done=s.history.find(h=>h.season===s.season&&h.eventId===ev.id),current=i===s.round&&!done;return `<article class="calendar-card ${current?'current':''} ${done?'done':''}"><span class="round-number">${String(i+1).padStart(2,'0')}</span><div><div class="row wrap"><span class="eyebrow" style="font-size:8px;margin:0">${country(ev.country)} ${esc(ev.label)}</span>${ev.special?'<span class="badge amber">24H-HIGHLIGHT</span>':''}${ev.lmgt3?'<span class="badge grey">LMGT3</span>':''}</div><h3>${esc(ev.name)}</h3><p>${duration(ev.minutes)} · ${esc(ev.character)}${ev.multiclass?' · Mehrklassenverkehr':''}</p></div><div>${done?`<span class="calendar-result">${done.dnf?'DNF':'P'+done.position}</span><div class="tiny muted center">${done.points} Punkte</div>`:current?`<button class="btn primary small-btn" data-nav="${s.race?'race':'garage'}">${s.race?'Rennen':'Vorbereiten'}</button>`:`<span class="pill">${duration(ev.minutes)}</span>`}</div></article>`;}).join('')}`;}
function renderMarket(){const s=state,off=E.offers(s),progress=Object.keys(D.CLASSES),last=s.archive[s.archive.length-1];return `${pageHead('DEIN WEG IM LANGSTRECKENSPORT',s.phase==='offseason'?'Das nächste Kapitel beginnt hier.':'Nicht jede große Karriere endet im Hypercar.','GT-Sport und Prototypen sind verschiedene Wege. Klassensiege in Le Mans sind ebenso ein Ziel.')}<div class="roadmap">${progress.map(cl=>`<div class="roadmap-stop ${s.classId===cl?'current':''}"><span class="eyebrow" style="font-size:8px;letter-spacing:1px">${s.classId===cl?'DU BIST HIER':s.history.some(h=>h.classId===cl)?'TEIL DEINER CHRONIK':'KARRIEREWEG'}</span><b>${cl}</b><small>${esc(D.CLASSES[cl].subtitle)}</small></div>`).join('')}</div><p class="small muted space-bottom">GT4 → GT3 oder LMP3. Über LMP2 kann es ins Hypercar gehen. GT3 bleibt als Profi-Karriere offen; GT1/GT2 sind keine zusätzlichen Stufen in dieser Spielversion.</p>${s.phase==='offseason'?`${last?`<section class="result-hero"><div class="result-position">P${last.position}</div><div class="result-copy"><span class="eyebrow green">SAISON ${last.year} ABGESCHLOSSEN</span><h1>${last.position===1?'Ein Team. Ein Titel.':'Eine Saison, auf der ihr aufbauen könnt.'}</h1><p>${num(last.points)} Punkte in der Teamwertung · Meister: ${esc(last.champion)}. Die vollständige Saison bleibt in deiner Chronik.</p><button class="btn ghost small-btn" data-nav="history">Zur Chronik ${icon('history')}</button></div></section>`:''}<div class="section-title"><h2>Deine Vertragsangebote</h2><span class="badge">VERBINDLICH WÄHLBAR</span></div><div class="grid3">${off.map(o=>`<article class="offer-card"><span class="badge ${o.stay?'':'grey'}">${o.classId}${o.stay?' · SICHERER PLATZ':''}</span><h3>${esc(o.name)}</h3><p><b class="green">${esc(o.title)}</b><br>${esc(o.text)}</p><div class="offer-money">${compact(s.role==='driver'?o.salary:o.funding)}</div><small>${s.role==='driver'?'Antrittsgeld beim Unterschreiben':'Finanzierung für das neue Programm'}</small><div class="stat-line" style="margin-top:18px"><span>Abstimmung</span><b>${num(o.quality)}/100</b></div>${meter(o.quality)}<button class="btn primary full" data-offer="${o.id}">Vertrag annehmen ${icon('arrow')}</button></article>`).join('')}</div>${s.role==='driver'?`<section class="panel space-top"><div class="row between wrap"><div><h3>Vom Cockpit an die Boxenmauer?</h3><p class="small" style="margin-top:6px">Behalte deine Chronik und führe die Karriere künftig als Teammanager weiter.</p></div>${button('In die Managerrolle wechseln','switch-role','ghost')}</div></section>`:''}`:`<section class="panel"><div class="panel-head"><h2>Was öffnet die nächste Tür?</h2><span class="badge">RUF ${num(s.reputation)}</span></div><p class="small">Neue Verträge werden am Saisonende angeboten. Ein Platz in deiner aktuellen Klasse ist immer verfügbar – auch nach einer schwierigen Saison.</p><div class="grid2 space-top">${D.CLASSES[s.classId].next.map(cl=>`<div class="panel flat"><div class="row between"><h3>${cl}-Programm</h3><span class="badge ${s.reputation>=D.CLASSES[cl].rep?'':'grey'}">${s.reputation>=D.CLASSES[cl].rep?'RUF ERREICHT':num(D.CLASSES[cl].rep)+' RUF NÖTIG'}</span></div><p class="tiny" style="margin:10px 0 12px">${s.reputation>=D.CLASSES[cl].rep?'Am Saisonende als Angebot verfügbar.':'Rennen beenden, im Verhältnis zum Auto überzeugen und Erfahrung sammeln.'}</p>${meter(Math.min(100,s.reputation/D.CLASSES[cl].rep*100))}</div>`).join('')}</div><div class="note space-top">${s.role==='manager'?'Nach zwei Managersaisonen bieten Investoren auch angrenzende Programme an. Ein knappes Budget beendet die Karriere nicht automatisch.':'Deine Werte wachsen durch Training und eigene Stints. Du brauchst nicht in jedem Rennen ein Podium, um dich weiterzuentwickeln.'}</div></section>`}<section class="panel space-top"><h3>Dein Fahrerlager-Profil</h3><div class="grid3 space-top"><div><div class="stat-line"><span>Ruf</span><b>${num(s.reputation)}/100</b></div>${meter(s.reputation)}</div><div><div class="stat-line"><span>Herstellerbeziehung</span><b>${num(s.team.affinity)}/100</b></div>${meter(s.team.affinity)}</div><div><div class="stat-line"><span>Zusammenhalt</span><b>${num(s.team.morale)}/100</b></div>${meter(s.team.morale)}</div></div><p class="tiny muted space-top">Ruf steuert neue Klassenangebote. Herstellerbeziehung und Zusammenhalt dokumentieren eure gemeinsame Entwicklung. Die Kategorien Bronze, Silber, Gold und Platin sind im Spiel vereinfacht – kein offizielles FIA-Rating.</p></section>`;}
function renderHistory(){const s=state,total=s.history.length,wins=s.history.filter(h=>h.position===1).length,podia=s.history.filter(h=>h.position>0&&h.position<=3).length,lemans=s.history.filter(h=>h.eventId==='lemans'&&h.position===1).length;return `${pageHead('DEINE KARRIERECHRONIK','Was bleibt, ist eure Geschichte.','Jede Saison, jedes große Rennen und jeder gemeinsame Erfolg werden in diesem Spielstand bewahrt.')}<div class="grid4">${metric('RENNEN',total,'Abgeschlossene Einsätze')}${metric('KLASSENSIEGE',wins,'Gemeinsame Siege')}${metric('PODIEN',podia,'Top 3 in deiner Klasse')}${metric('LE-MANS-SIEGE',lemans,'Klassen- oder Gesamtsieg')}</div><div class="section-title"><h2>Eure Meilensteine</h2></div>${s.achievements.length?`<div class="grid3">${s.achievements.map(a=>`<div class="achievement">${icon('trophy')}<div><b>${esc(a.name)}</b><small>Saison ${a.season}</small></div></div>`).join('')}</div>`:`<div class="empty">${icon('flag')}<h3>Deine Geschichte beginnt an der Startlinie.</h3><p>Beende dein erstes Rennen, um die erste Zielflagge in deiner Chronik festzuhalten.</p></div>`}<div class="section-title"><h2>Saisonarchiv</h2><span class="pill">${s.archive.length} abgeschlossene Saisonen</span></div>${[...new Set(s.history.map(h=>h.season))].reverse().map(season=>{const entries=s.history.filter(h=>h.season===season),ar=s.archive.find(a=>a.season===season);return `<details class="archive-year" ${season===s.season?'open':''}><summary><div class="row"><span class="year">${entries[0].year}</span><div><h3>${esc(entries[0].team)} · ${entries[0].classId}</h3><small>${ar?'Abgeschlossen · Teamwertung P'+ar.position:'Saison läuft'} · ${entries.length} Rennen</small></div></div><span class="green">+</span></summary><div class="archive-content"><div class="big-table-wrap"><table class="big-table"><thead><tr><th>Rennen</th><th>Ergebnis</th><th>Punkte</th></tr></thead><tbody>${entries.map(h=>`<tr><td>${esc(h.eventName)}</td><td>${h.dnf?'DNF':'P'+h.position}</td><td>${h.points}</td></tr>`).join('')}</tbody></table></div>${ar?`<p class="table-note">Saisonmeister: ${esc(ar.champion)} · Dein Team: ${ar.points} Punkte.</p><details class="help space-top"><summary>Vollständige Team-Endwertung</summary><div class="big-table-wrap"><table class="big-table"><tbody>${ar.standings.teams.map((t,i)=>`<tr class="${t.own?'own':''}"><td>${i+1}</td><td>${esc(t.name)}</td><td>${t.points}</td></tr>`).join('')}</tbody></table></div></details>`:''}</div></details>`;}).join('')||'<div class="empty"><p>Nach der ersten Zielflagge erscheinen deine Rennergebnisse hier.</p></div>'}`;}
function helpContent(){return `<div class="help"><details open><summary>Wie funktioniert das Spiel?</summary><p>Bereite das Wochenende vor, lege euren Stintplan fest und starte Qualifying & Rennen. In der Rennzentrale entscheidest du an wichtigen Punkten. Ein Klick simuliert das nächste Kapitel. Ohne Klick läuft keine Zeit weiter. Du kannst jederzeit Tabellen und Teamseiten öffnen oder den Spielstand sichern.</p></details><details><summary>Was ist der Unterschied zwischen Fahrer und Manager?</summary><p>Als Fahrer beginnst du in GT4, entwickelst deine Fähigkeiten und beeinflusst deinen eigenen Stint. Wenn dein Teamkollege fährt, arbeitet er mit seinem eigenen Fahrstil und seinen Stärken; du kannst dich erholen, Telemetrie besprechen oder Rückhalt geben. Kritische Boxenentscheidungen sind gemeinsame Teamentscheidungen. Als Manager wählst du die Startklasse, verpflichtest Fahrer, entwickelst den Betrieb und bestimmst das Tempo über alle Stints.</p></details><details><summary>Warum wechseln Reifen und Schäden nicht mit dem Fahrer?</summary><p>Weil sie zum Auto gehören. Ein Fahrerwechsel allein setzt sie nicht zurück. Ein neuer Reifensatz muss im Boxenstopp montiert werden; Schäden verschwinden erst durch Reparatur. Wer das Auto schont, erleichtert auch den nächsten Einsatz. Tankstopps und notwendige Fahrerwechsel erledigt die Crew nach dem vereinfachten Spielplan automatisch.</p></details><details><summary>Schnellmodus oder Standardmodus?</summary><p>Beide nutzen dieselben Autos, Fahrer und dieselbe Simulation in Fünf-Minuten-Schritten. Schnellmodus: Bei langen Rennen entscheidest du höchstens stündlich, sonst alle 20 Minuten. Standardmodus: Bei langen Rennen alle 30 Minuten, sonst alle 10 Minuten. Gleiche Entscheidungen werden dadurch nicht garantiert gleich oft getroffen. Die Karriereinhalte sind identisch. Ein Moduswechsel gilt für das nächste Rennen.</p></details><details><summary>Wer darf wie lange fahren?</summary><p>Bis einschließlich drei Stunden sind zwei Fahrer aktiv, darüber drei. Der dritte ist bei kurzen Rennen Reserve. Das Spiel plant Wechsel nach maximal 70 Minuten oder nach einem kürzeren Anteil der Gesamtdauer. In der Fahrerkarriere bist du immer Teil der aktiven Besetzung. Ermüdung steigt im Auto und sinkt in der Pause. Das ist eine vereinfachte Spielregel, kein vollständiges Reglement einer realen Serie.</p></details><details><summary>Was bedeutet Bronze, Silber, Gold oder Platin?</summary><p>Das sind hier vereinfachte Spieleinstufungen, keine offizielle FIA-Einstufung. Junge neue Fahrer starten im Spiel in Silber, ältere Einsteiger gegebenenfalls in Bronze; spätere Anpassungen basieren auf Spielwerten und Ruf. Es ist ausdrücklich keine reale universelle Level-Leiter. Für LMGT3 berücksichtigt das Spiel einen Bronze-Fahrer und höchstens einen Gold/Platin-Fahrer. In den Prototypen-Nachwuchsklassen bleibt ein Bronze/Silber-Platz erhalten.</p></details><details><summary>Welche Karrierewege sind spielbar?</summary><p>GT4 → GT3 oder LMP3. Danach sind LMP2 und Hypercar erreichbar. Auch eine dauerhafte GT3-Karriere mit großen Klassensiegen ist möglich. Le Mans ist ein Rennen, keine eigene Klasse: Du kannst dort in LMGT3, LMP2 oder Hypercar fahren. Im GT3-Spielkalender ist die Le-Mans-Einladung absichtlich direkt eingebaut. LMP3 startet hier nicht bei den 24 Stunden von Le Mans.</p></details><details><summary>Kann meine Karriere in einer Sackgasse enden?</summary><p>Eine schwierige Saison kostet Ergebnisse, aber nicht automatisch dein nächstes Cockpit. Nach jeder Saison ist ein Fortsetzungsvertrag verfügbar. Bei kritischem Team-Budget gibt es ein Rettungsbudget. Aufstiegsmöglichkeiten hängen vor allem vom Ruf ab. Das Spiel soll Rückschläge erzählen, nicht einen Spielstand unspielbar machen.</p></details><details><summary>Wie sicher sind meine Spielstände?</summary><p>Das Spiel speichert nach jeder Entscheidung in einem von drei lokalen Speicherplätzen. Die Daten bleiben in diesem Browser; es gibt kein Konto und keine Cloud-Synchronisation. Browserdaten können gelöscht werden. Sichere daher zusätzlich eine JSON-Datei über „Spielstand exportieren“. Sie enthält auch ein laufendes Rennen und kann auf einem anderen Gerät importiert werden. Manche Dateivorschauen oder private Browser erlauben kein dauerhaftes Speichern; dann weist dich das Spiel darauf hin.</p></details><details><summary>Was ist Realität, was ist Spiel?</summary><p>Fahrzeugklassen und die Idee gemeinsamer Langstreckenbesetzungen orientieren sich am Motorsport. Teams, Personen, Leistungswerte, Budgets, Verträge und Kalender sind fiktiv. Fahrzeiten, Neutralisationen, Einladungen, Reparaturen und die Punktewertung sind vereinfacht. Es gibt keine echten Herstellerlizenzen, keinen Online-Mehrspieler und keine Herstellerkarriere in Version 1. Die Zeichnung des Autos ist eine eigene stilisierte Darstellung.</p><p>Hintergrundquellen: ${D.SOURCES.map(x=>`<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.name)}</a>`).join(' · ')}. Die Links werden nur geöffnet, wenn du sie antippst.</p></details><details><summary>Bedienung & Tastatur</summary><p>Die drei Rennentscheidungen können am Computer auch mit 1, 2 und 3 gewählt werden. Escape schließt ein Dialogfenster. Auf dem Handy findest du weitere Seiten unter „Mehr“. Ein Boxenauftrag verändert das Auto sofort, seine Zeitkosten werden im nächsten Kapitel simuliert. Es ist höchstens ein manueller Auftrag pro Kapitel möglich.</p></details></div>`;}
function renderSettings(){const s=state;return `${pageHead('DEIN SPIEL, DEIN TEMPO','Speichern & Spielhilfe','Drei getrennte Spielstände. Keine Anmeldung. Deine Daten bleiben bei dir.')}<section class="panel space-bottom"><div class="settings-row"><div><h3>Rennmodus</h3><p>Der Standardmodus hat mehr Entscheidungen.<br>Änderungen gelten ab dem nächsten Rennen.</p></div><div class="switch-group"><button data-mode="quick" class="${s.mode==='quick'?'active':''}">Schnell</button><button data-mode="standard" class="${s.mode==='standard'?'active':''}">Standard</button></div></div><div class="settings-row"><div><h3>Speicherplatz ${activeSlot} ist aktiv</h3><p>${storageOK?'Jede Entscheidung wird automatisch lokal gesichert.':'Speichern ist blockiert. Exportiere deinen Spielstand regelmäßig.'}</p></div><span class="badge ${storageOK?'':'amber'}">${storageOK?'AUTOSAVE':'EXPORT NÖTIG'}</span></div><div class="settings-row"><div><h3>Eine eigene Sicherung</h3><p>Exportiere eine JSON-Datei, auch mitten im Rennen.</p></div>${button(icon('download')+' Export','export','primary')}</div><div class="settings-row"><div><h3>Spielstand übernehmen</h3><p>Vor dem Import wird der Inhalt geprüft und der Zielplatz bestätigt.</p></div>${button(icon('upload')+' Import','import','ghost')}</div></section>${savedCards(true)}<div class="section-title"><h2>Alles Wichtige zum Spiel</h2>${icon('help')}</div><section class="panel">${helpContent()}</section><div class="note space-top">ENDURANCE 1.0 · Eigenständiges, nicht offiziell verbundenes Motorsport-Entscheidungsspiel. Keine externen Dienste oder KI-Schlüssel nötig. Ein öffentlicher Link ist erst nach Hosting dieser Dateien vorhanden.</div>`;}
function render(){const scroll=window.scrollY;app.innerHTML=state?shell(({garage:renderGarage,race:renderRace,team:renderTeam,standings:renderStandings,calendar:renderCalendar,market:renderMarket,history:renderHistory,settings:renderSettings}[view]||renderGarage)()):renderHome();renderModal();if(window.scrollY!==scroll)window.scrollTo({top:scroll});}
function readNewForm(){const get=id=>document.getElementById(id)?.value;const old=modal?.options||{};return {...old,name:get('career-name')??old.name,age:Number(get('career-age')??old.age),country:get('career-country')??old.country,slot:Number(get('career-slot')??old.slot),classId:get('career-class')??old.classId,teamName:get('career-team')??old.teamName,teamStyle:get('career-style')??old.teamStyle,mode:get('career-mode')??old.mode};}
function newCareer(role='driver',scenario=null){let slot=[1,2,3].find(i=>!readSlot(i))||1;modal={type:'new',options:{role,scenario,name:'Mario Trefflinger',age:21,country:'AT',slot,classId:scenario?'Hypercar':'GT4',teamName:'',teamStyle:'balanced',mode:'quick'}};renderModal();}
function confirm(title,text,callback,label='Bestätigen'){modal={type:'confirm',title,text,callback,label};renderModal();}
function createFrom(o){state=E.createCareer({...o,seed:crypto?.getRandomValues?crypto.getRandomValues(new Uint32Array(1))[0]:Math.floor(Math.random()*4294967295)});activeSlot=o.slot;view='garage';modal=null;save();render();window.scrollTo(0,0);toast('Deine Karriere ist gestartet. Viel Erfolg mit der Mannschaft!');}
function modalFrame(title,body){return `<div class="modal-overlay" data-overlay="true"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Dialog schließen">${icon('close')}</button></header><div class="modal-content">${body}</div></section></div>`;}
function renderModal(){document.body.classList.toggle('modal-open',!!modal);if(!modal){modalRoot.innerHTML='';return;}let body='',title='';
 if(modal.type==='new'){const o=modal.options;title=o.scenario?'24h-Challenge: Le Mans':'Dein erstes Kapitel';body=`<form id="new-career-form"><div class="role-select"><button type="button" data-role="driver" class="role-option ${o.role==='driver'?'active':''}">${icon('steering')}<b>Fahrerkarriere</b><small>${o.scenario?'Du teilst dir das Hypercar mit zwei Kollegen.':'Du beginnst in GT4 und entwickelst dich weiter.'}</small></button><button type="button" data-role="manager" class="role-option ${o.role==='manager'?'active':''}">${icon('team')}<b>Managerkarriere</b><small>Du entscheidest für Fahrer, Team und Strategie.</small></button></div><div class="form-grid"><label class="field mobile-full">Dein Name<input id="career-name" name="name" required maxlength="40" autocomplete="off" value="${esc(o.name)}"></label><label class="field">Alter<input id="career-age" type="number" min="16" max="70" step="1" value="${o.age}" required></label><label class="field">Nationalität<select id="career-country">${[['AT','Österreich'],['DE','Deutschland'],['CH','Schweiz'],['HR','Kroatien'],['IT','Italien'],['FR','Frankreich'],['GB','Großbritannien'],['US','USA']].map(([c,n])=>`<option value="${c}" ${o.country===c?'selected':''}>${country(c)} ${n}</option>`).join('')}</select></label><label class="field">Startklasse<select id="career-class" ${o.role==='driver'||o.scenario?'disabled':''}>${Object.keys(D.CLASSES).map(cl=>`<option value="${cl}" ${((o.scenario?'Hypercar':o.role==='driver'?'GT4':o.classId)===cl)?'selected':''}>${cl}</option>`).join('')}</select></label><label class="field">Spieltempo<select id="career-mode"><option value="quick" ${o.mode==='quick'?'selected':''}>Schnell – weniger Entscheidungen</option><option value="standard" ${o.mode==='standard'?'selected':''}>Standard – mehr Entscheidungen</option></select></label><label class="field mobile-full">Teamname (optional)<input id="career-team" maxlength="40" placeholder="Alpenwerk Racing" value="${esc(o.teamName)}" autocomplete="off"></label><label class="field">Ausgangslage<select id="career-style"><option value="academy" ${o.teamStyle==='academy'?'selected':''}>Aufbauprogramm</option><option value="balanced" ${o.teamStyle==='balanced'?'selected':''}>Ausgewogenes Team</option><option value="front" ${o.teamStyle==='front'?'selected':''}>Stärkeres Auto, weniger Budget</option></select></label><label class="field">Speicherplatz<select id="career-slot">${[1,2,3].map(i=>`<option value="${i}" ${o.slot===i?'selected':''}>Platz ${i} · ${readSlot(i)?'belegt':'frei'}</option>`).join('')}</select></label></div><div class="note space-top">${o.scenario?'Du startest direkt bei den 24 Stunden von Le Mans. Diese Challenge hat ihren eigenen Spielstand.':'Eine Saison umfasst sechs Rennen. Verträge und Klassenwechsel folgen am Saisonende.'} Alle Teams und Budgets sind fiktiv.</div><div class="modal-buttons"><button type="button" class="btn ghost" data-action="close-modal">Zurück</button><button type="submit" class="btn primary">Karriere beginnen ${icon('arrow')}</button></div></form>`;}
 else if(modal.type==='help'){title='Willkommen in der Langstrecke';body=helpContent();}
 else if(modal.type==='confirm'){title=esc(modal.title);body=`<p>${esc(modal.text)}</p><div class="modal-buttons">${button('Abbrechen','close-modal','ghost')}${button(esc(modal.label),'confirm','primary')}</div>`;}
 else if(modal.type==='more'){title='Dein Paddock';body=`<div class="nav-list">${navs.map(([id,ico,n])=>`<button class="nav-item ${view===id?'active':''}" data-nav="${id}">${icon(ico)}${n}</button>`).join('')}</div><div class="divider"></div>${button('Zum Hauptmenü','home','ghost full')}`;}
 else if(modal.type==='pit'){const c=E.ownCar(state),r=state.race;title='Dein Boxenauftrag';body=`<p>Auftanken ist enthalten. Neue Reifen, Fahrerwechsel und Reparaturen kosten zusätzliche Zeit. Das Rennen läuft erst mit der nächsten Rennentscheidung weiter.</p><form id="pit-form"><div class="form-grid"><label class="field mobile-full">Wer fährt danach?<select id="pit-driver">${driverOptions(c.driver,c.drivers,c.active)}</select></label><label class="field">Reifen<select id="pit-tyres"><option value="keep">Reifen behalten (${num(c.tyres)} %)</option><option value="slick" ${E.getWeather(r)<50?'selected':''}>Neue Slicks</option><option value="wet" ${E.getWeather(r)>=50?'selected':''}>Neue Regenreifen</option></select></label><label class="field">Reparatur<select id="pit-repair"><option value="none">Keine Reparatur</option><option value="quick">Schnell: bis zu 14 % Schaden</option><option value="full">Vollständig: ${num(c.damage)} %</option></select></label></div><div class="note space-top">Aktuell: ${num(c.fuel)} % Tank · ${num(c.tyres)} % Reifen · ${num(c.damage)} % Schaden. Auch dein nächster Teamkollege übernimmt genau diesen Zustand, sofern du ihn nicht ändern lässt.</div><div class="modal-buttons"><button type="button" class="btn ghost" data-action="close-modal">Zurück</button><button type="submit" class="btn primary">Boxenauftrag ausführen ${icon('wrench')}</button></div></form>`;}
 else if(modal.type==='qualifying'){title='Qualifying · '+esc(state.race.event.name);const rows=state.race.qualifying.filter(x=>x.classId===state.classId);body=`<p>Die Startreihenfolge wurde aus Fahrer-Tempo, Auto-Abstimmung, Vorbereitung und dem gewählten Qualifying-Risiko simuliert.</p><table class="big-table"><thead><tr><th>Pos.</th><th>Team</th><th>Zeit</th></tr></thead><tbody>${rows.map((x,i)=>`<tr class="${x.own?'own':''}"><td>${i+1}</td><td>${esc(x.name)}</td><td>${Math.floor(x.time/60)}:${num(x.time%60,3).padStart(6,'0')}</td></tr>`).join('')}</tbody></table>`;}
 modalRoot.innerHTML=modalFrame(title,body);queueMicrotask(()=>modalRoot.querySelector('[data-action="close-modal"]')?.focus({preventScroll:true}));
}
function exportSave(){if(!state){toast('Lade zuerst einen Spielstand.',true);return;}try{const blob=new Blob([E.serialise(state)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`ENDURANCE-S${state.season}-${state.classId}-Spielstand.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1500);toast('Deine Sicherungsdatei wurde erzeugt.');}catch(err){toast(err.message,true);}}
function chooseRace(id){if(busy)return;busy=true;mutate(()=>E.choose(state,id));setTimeout(()=>busy=false,140);}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;
 if(el.dataset.nav){navigate(el.dataset.nav);return;}
 if(el.dataset.role){const o=readNewForm();o.role=el.dataset.role;if(o.role==='driver'&&!o.scenario)o.classId='GT4';modal={type:'new',options:o};renderModal();return;}
 if(el.dataset.load){openSlot(Number(el.dataset.load));return;}
 if(el.dataset.choice){chooseRace(el.dataset.choice);return;}
 if(el.dataset.prepare){mutate(()=>E.prepare(state,el.dataset.prepare),'Deine Wochenend-Vorbereitung ist abgeschlossen.');return;}
 if(el.dataset.interview){mutate(()=>E.interview(state,el.dataset.interview),'Deine Antwort ist im Team angekommen.');return;}
 if(el.dataset.table){tableTab=el.dataset.table;render();return;}
 if(el.dataset.timing){timingTab=el.dataset.timing;render();return;}
 if(el.dataset.upgrade){mutate(()=>E.develop(state,el.dataset.upgrade),'Die Verbesserung ist für das nächste Rennen verfügbar.');return;}
 if(el.dataset.hire){const d=E.candidates(state).find(x=>x.id===el.dataset.hire),slot=hireSlot;confirm('Fahrer verpflichten?',`${d.name} ersetzt ${state.team.drivers[slot].name}. Die einmalige Ablöse beträgt ${money(d.price)}.`,()=>mutate(()=>E.hire(state,d.id,slot),'Deine neue Besetzung steht.'),'Verpflichten');return;}
 if(el.dataset.sponsor){mutate(()=>E.chooseSponsor(state,el.dataset.sponsor),'Der Partnervertrag ist für diese Saison unterschrieben.');return;}
 if(el.dataset.offer){const id=el.dataset.offer;mutate(()=>{E.acceptOffer(state,id);view='garage';},'Willkommen im nächsten Kapitel deiner Karriere.');window.scrollTo(0,0);return;}
 if(el.dataset.mode){mutate(()=>{state.mode=el.dataset.mode;},'Das neue Spieltempo gilt ab dem nächsten Rennen.');return;}
 if(el.dataset.copy){const target=Number(el.dataset.copy),run=()=>{activeSlot=target;save();render();toast('Spielstand in Platz '+target+' gesichert.');};if(readSlot(target)&&target!==activeSlot)confirm('Speicherplatz ersetzen?','Der bisherige Inhalt von Speicherplatz '+target+' wird durch deine aktuelle Karriere ersetzt.',run,'Hier sichern');else run();return;}
 if(el.dataset.delete){const slot=Number(el.dataset.delete);confirm('Spielstand wirklich löschen?','Der lokale Spielstand in Platz '+slot+' wird gelöscht. Bereits exportierte Sicherungsdateien bleiben erhalten.',()=>{memory.delete(slot);try{localStorage.removeItem(KEY(slot));localStorage.removeItem(KEY(slot)+'-date');}catch{}if(slot===activeSlot)state=null;render();},'Löschen');return;}
 const action=el.dataset.action;if(!action)return;
 if(action==='new-driver')newCareer('driver');
 else if(action==='new-manager')newCareer('manager');
 else if(action==='challenge')newCareer('driver','lemans');
 else if(action==='help'){modal={type:'help'};renderModal();}
 else if(action==='close-modal'){modal=null;renderModal();}
 else if(action==='more'){modal={type:'more'};renderModal();}
 else if(action==='home'){save();state=null;modal=null;render();window.scrollTo(0,0);}
 else if(action==='start-race'){mutate(()=>{E.startRace(state);view='race';});window.scrollTo(0,0);}
 else if(action==='next-round'){mutate(()=>{E.nextRound(state);view=state.phase==='offseason'?'market':'garage';});window.scrollTo(0,0);}
 else if(action==='pit'){modal={type:'pit'};renderModal();}
 else if(action==='qualifying'){modal={type:'qualifying'};renderModal();}
 else if(action==='export')exportSave();
 else if(action==='import')document.getElementById('import-file').click();
 else if(action==='confirm'){const cb=modal?.callback;modal=null;renderModal();try{cb?.();}catch(err){toast(err.message,true);}}
 else if(action==='switch-role')confirm('An die Boxenmauer wechseln?','Deine bisherige Karriere bleibt in der Chronik. Ab jetzt übernimmst du dauerhaft die Managerrolle und wählst anschließend einen Vertrag für die nächste Saison.',()=>mutate(()=>E.switchToManager(state),'Du bist jetzt Teammanager.'),'Rolle wechseln');
});
document.addEventListener('change',e=>{const el=e.target;
 if(el.dataset.plan){const key=el.dataset.plan,val=['start','night','finish'].includes(key)?Number(el.value):el.value;mutate(()=>E.setPlan(state,{[key]:val}));}
 else if(el.id==='hire-slot')hireSlot=Number(el.value);
});
document.addEventListener('submit',e=>{if(e.target.id==='new-career-form'){e.preventDefault();const o=readNewForm();if(readSlot(o.slot)){confirm('Speicherplatz '+o.slot+' ersetzen?','Dort liegt bereits eine Karriere. Beim Start wird sie ersetzt. Ein anderer Speicherplatz schützt deine bisherige Karriere.',()=>createFrom(o),'Neue Karriere starten');}else createFrom(o);}
 else if(e.target.id==='pit-form'){e.preventDefault();const opts={driver:Number(document.getElementById('pit-driver').value),tyres:document.getElementById('pit-tyres').value,repair:document.getElementById('pit-repair').value};modal=null;mutate(()=>E.pit(state,opts),'Boxenauftrag ausgeführt. Der Zeitverlust zählt im nächsten Kapitel.');}
});
document.getElementById('import-file').addEventListener('change',async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;try{if(file.size>2500000)throw new Error('Diese Datei ist zu groß. Erwartet wird ein ENDURANCE-JSON-Spielstand.');const imported=E.parse(await file.text());const slot=state?activeSlot:[1,2,3].find(i=>!readSlot(i))||1;confirm('Geprüften Spielstand importieren?',`${imported.player.name} · ${imported.classId} · Saison ${imported.season}. Der Import wird in Speicherplatz ${slot} übernommen${readSlot(slot)?' und ersetzt dessen bisherigen Inhalt':''}.`,()=>{state=imported;activeSlot=slot;view=state.race?'race':state.phase==='offseason'?'market':'garage';save();render();window.scrollTo(0,0);toast('Spielstand übernommen. Deine Karriere geht genau hier weiter.');},'Spielstand übernehmen');}catch(err){toast(err.message,true);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=null;renderModal();return;}if(modal&&e.key==='Tab'){const items=[...modalRoot.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),a[href],summary')];if(!items.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}return;}if(modal||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(['1','2','3'].includes(e.key)&&state?.race&&!state.race.finished&&view==='race'){e.preventDefault();const ch=E.choices(state)[Number(e.key)-1];if(ch)chooseRace(ch.id);}});
window.addEventListener('storage',e=>{if(state&&e.key===KEY(activeSlot))toast('Dieser Speicherplatz wurde in einem anderen Tab geändert. Lade ihn unter „Speichern & Hilfe“ neu, bevor du weiterspielst.',true);});
// Every successful mutation is already saved; closing a stale tab must not overwrite a newer save.
render();
if('serviceWorker'in navigator&&/^https?:$/.test(location.protocol)){navigator.serviceWorker.register('./sw.js').catch(()=>{});}
})();
